"""MCP App resource for validated, account-private video results."""

VIDEO_VIEWER_URI = "ui://gemini-webapi-mcp/video-result-v1.html"


def video_viewer_resource_meta() -> dict:
    """The player loads only the video blob embedded in its tool result."""
    return {
        "ui": {
            "prefersBorder": False,
            "csp": {"connectDomains": [], "resourceDomains": []},
        },
        "openai/widgetCSP": {"connect_domains": [], "resource_domains": []},
        "openai/ui": {"availableDisplayModes": ["inline", "fullscreen"]},
    }


VIDEO_VIEWER_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<style>:root{color-scheme:light dark;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}html,body{margin:0;background:transparent;color:CanvasText}body{padding:4px}main{width:100%}#status{margin:5px 4px 9px;font-size:13px;color:color-mix(in srgb,CanvasText 65%,transparent)}#frame{position:relative;width:100%;overflow:hidden;border:1px solid color-mix(in srgb,CanvasText 15%,transparent);border-radius:14px;background:#000;aspect-ratio:16/9;display:grid;place-items:center}video{display:block;width:100%;height:100%;object-fit:contain;background:#000}#message{padding:24px;text-align:center;color:#ddd;line-height:1.45}#message[hidden],video[hidden],#actions[hidden]{display:none}#actions{display:flex;gap:8px;padding:10px 4px 2px}.action{min-height:40px;padding:0 14px;border:1px solid color-mix(in srgb,CanvasText 15%,transparent);border-radius:999px;background:color-mix(in srgb,Canvas 96%,CanvasText 4%);color:CanvasText;text-decoration:none;display:inline-grid;place-items:center;cursor:pointer}.action:focus-visible{outline:3px solid #0b6bcb;outline-offset:2px}@media(max-width:480px){body{padding:2px}#frame{border-radius:12px}}</style></head>
<body><main id="app" aria-busy="true"><p id="status">Waiting for the generated video result…</p><section id="frame"><video id="video" controls playsinline preload="metadata" hidden></video><div id="message">Loading video…</div></section><div id="actions" hidden><a id="download" class="action" download="gemini-video">Download</a><button id="expand" class="action" type="button">Fullscreen</button></div></main>
<script>(()=>{const app=document.getElementById("app"),status=document.getElementById("status"),frame=document.getElementById("frame"),video=document.getElementById("video"),message=document.getElementById("message"),actions=document.getElementById("actions"),download=document.getElementById("download"),expand=document.getElementById("expand");let objectUrl="",lastHeight=0,frameId=0;function envelope(v){return!v||typeof v!=="object"?null:v.mcp_tool_result||v.mcpToolResult||v.call_tool_result||v.callToolResult||v.result||v}function resize(){if(frameId)return;frameId=requestAnimationFrame(()=>{frameId=0;const h=Math.max(160,Math.min(1800,Math.ceil(document.documentElement.scrollHeight)));if(Math.abs(h-lastHeight)<2)return;lastHeight=h;if(window.openai&&typeof window.openai.notifyIntrinsicHeight==="function")try{window.openai.notifyIntrinsicHeight(h)}catch(_){}})}function fail(text){app.setAttribute("aria-busy","false");video.hidden=true;message.hidden=false;message.textContent=text;status.textContent="Video unavailable";actions.hidden=true;resize()}function render(v){const r=envelope(v);if(!r)return;const blocks=Array.isArray(r.content)?r.content:[],block=blocks.find(x=>x&&x.type==="resource"&&x.resource&&typeof x.resource.blob==="string"&&/^(video\/(?:mp4|webm))$/i.test(x.resource.mimeType||x.resource.mime_type||""));if(!block){if(r.isError)fail("Video generation failed.");return}try{const mime=block.resource.mimeType||block.resource.mime_type,binary=atob(block.resource.blob),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(new Blob([bytes],{type:mime}));video.src=objectUrl;download.href=objectUrl;download.download=(r.structuredContent&&r.structuredContent.artifact&&r.structuredContent.artifact.filename)||"gemini-video";const a=r.structuredContent&&r.structuredContent.artifact;if(a&&a.width>0&&a.height>0)frame.style.aspectRatio=`${a.width}/${a.height}`;video.hidden=false;message.hidden=true;actions.hidden=false;status.textContent="Generated video";app.setAttribute("aria-busy","false");resize()}catch(_){fail("The video payload could not be decoded.")}}video.addEventListener("loadedmetadata",resize);video.addEventListener("error",()=>fail("This video could not be played by the client."));expand.onclick=async()=>{if(window.openai&&typeof window.openai.requestDisplayMode==="function")try{await window.openai.requestDisplayMode({mode:"fullscreen"})}catch(_){}if(video.requestFullscreen)try{await video.requestFullscreen()}catch(_){}resize()};render(window.openai&&(window.openai.toolResponseMetadata||window.openai.toolOutput));window.addEventListener("openai:set_globals",e=>{const g=e.detail&&e.detail.globals;if(g)render(g.toolResponseMetadata||g.toolOutput)});window.addEventListener("message",e=>{if(e.data&&e.data.method==="ui/notifications/tool-result")render(e.data.params)});const observer=new ResizeObserver(resize);observer.observe(app);window.addEventListener("resize",resize,{passive:true});window.addEventListener("orientationchange",resize,{passive:true});window.addEventListener("pagehide",()=>{observer.disconnect();cancelAnimationFrame(frameId);if(objectUrl)URL.revokeObjectURL(objectUrl)},{once:true});resize()})();</script></body></html>"""
